def is_palindrome(s):
    t = s.lower()
    return t == t[::-1]

def safe_mean(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)

def second_largest(nums):
    d = sorted(set(nums), reverse=True)
    return d[1] if len(d) > 1 else None

def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        s = ('Fizz' if i % 3 == 0 else '') + ('Buzz' if i % 5 == 0 else '')
        out.append(s or str(i))
    return out
